const $=(s)=>document.querySelector(s); const api=async(p,o={})=>{const r=await fetch(p,{headers:{'Content-Type':'application/json'},...o}); const text=await r.text(); let b={}; try{b=text?JSON.parse(text):{};}catch{b={error:text};} if(!r.ok){const msg=b.error||b.message||text||`Request failed (${r.status})`; if(/period .*closed|Save is not allowed|Posting is not allowed|Reversal cannot be posted/i.test(msg)) alert(msg); throw new Error(msg);} return b;};
const detailRoutePattern=/^\/(?:ar\/(?:doc\/|payments\/new|invoices\/new|credit-memos\/new|debit-memos\/new|customers\/[^/]+)|ap\/(?:bills\/[^/]+|payments\/[^/]+|vendors\/[^/]+|incoming-documents\/[^/]+\/review)|finance\/(?:journal|journal-entries)\/[^/]+|inventory\/(?:items|documents|transactions)\/[^/]+|purchase-orders\/(?:orders|receipts)\/[^/]+|sales-orders\/(?:orders|shipments)\/[^/]+)$/;
function captureNavigationState(){const searches={};document.querySelectorAll('.grid-search[data-grid]').forEach(input=>searches[input.dataset.grid]=input.value);const pages={};document.querySelectorAll('.grid-pagination span[id$="_page"]').forEach(label=>{const match=label.textContent.match(/Page (\d+)/);if(match)pages[label.id.replace(/_page$/,'')]=Number(match[1]);});return {searches,pages,activeTabs:[...document.querySelectorAll('.tab.active[data-tab]')].map(tab=>tab.dataset.tab),scrollY:window.scrollY};}
function rememberReturnTo(target){const targetPath=new URL(target,location.origin).pathname;if(!detailRoutePattern.test(targetPath)||detailRoutePattern.test(location.pathname))return;sessionStorage.setItem('erpReturnTo',JSON.stringify({targetPath,returnUrl:location.pathname+location.search,state:captureNavigationState(),createdAt:Date.now()}));}
function restoreNavigationState(state={}){Object.entries(state.searches||{}).forEach(([grid,value])=>{const input=document.querySelector(`.grid-search[data-grid='${grid}']`);if(input){input.value=value;input.dispatchEvent(new Event('input'));}});Object.entries(state.pages||{}).forEach(([grid,page])=>{for(let i=1;i<page;i++)document.getElementById(grid+'_next')?.click();});(state.activeTabs||[]).forEach(tab=>document.querySelector(`.tab[data-tab='${CSS.escape(tab)}']`)?.click());window.scrollTo(0,Number(state.scrollY||0));}
async function returnAfterSave(fallback){let context=null;try{context=JSON.parse(sessionStorage.getItem('erpReturnTo')||'null');}catch{}const current=location.pathname,valid=context&&Date.now()-Number(context.createdAt||0)<28800000&&(context.targetPath===current||/\/(?:new|__new__)$/.test(context.targetPath));const destination=valid?context.returnUrl:fallback,state=valid?context.state:null;sessionStorage.removeItem('erpReturnTo');history.pushState({},'',destination);await router();if(state)setTimeout(()=>restoreNavigationState(state),0);}
