 const editable=['Saved','Draft'].includes(je.status);let lines=(je.lines||[]).map(l=>({...l}));const accountName=code=>accounts.find(a=>String(a.accountNumber)===String(code))?.accountTitle||'';const headerRef=je.sourceRef||lines.find(l=>l.sourceReference)?.sourceReference||'';const headerHref=sourceHref(headerRef);$('#title').textContent=`Journal Entry ${je.jeNumber}`;
