const renderDocs=()=>{const rows=elig.map((d,i)=>{const ex=state.applications.find(a=>a.documentId===d.id)||{}; return `<tr><td><input class='pickDoc' data-id='${d.id}' type='checkbox' ${ex.amountPaid>0?'checked':''} ${readonly?'disabled':''}></td><td>${d.type}</td><td><a class='link' href='/ap/bills'>${d.id}</a></td><td>${d.vendorInvoiceNumber||d.id}</td><td>${d.date||''}</td><td>${d.dueDate||''}</td><td>${fmtMoney(Number(d.amount||0))}</td><td class='openBal'>${fmtMoney(Number(d.balance||0))}</td><td><input class='amtPaid' data-id='${d.id}' type='number' value='${Number(ex.amountPaid||0)}' ${readonly?'readonly':''}></td><td class='remainBal'>${fmtMoney(Math.max(0,Number(d.balance||0)-Number(ex.amountPaid||0)))}</td><td>${d.status||''}</td></tr>`}).join(''); $('#docsGrid').innerHTML=`<table><tr><th></th><th>Document Type</th><th>Reference Number</th><th>Vendor Invoice Number</th><th>Document Date</th><th>Due Date</th><th>Original Amount</th><th>Open Balance</th><th>Applied Amount</th><th>Remaining Balance After Application</th><th>Status</th></tr>${rows}</table>`; const auto=()=>{let rem=Number($('#pAmount').value||0); document.querySelectorAll('.pickDoc').forEach(c=>{const doc=elig.find(d=>d.id===c.dataset.id); const amtInp=document.querySelector(`.amtPaid[data-id='${doc.id}']`); if(!c.checked){amtInp.value='0'; return;} const ap=Math.min(rem,Number(doc.balance||0)); amtInp.value=ap; rem-=ap;}); updateFromGrid();}; const updateFromGrid=()=>{state.applications=[...document.querySelectorAll('.amtPaid')].map(i=>({documentId:i.dataset.id,billId:i.dataset.id,amountPaid:Number(i.value||0)})).filter(x=>x.amountPaid>0); document.querySelectorAll('.amtPaid').forEach(i=>{const doc=elig.find(d=>d.id===i.dataset.id); const rem=Math.max(0,Number(doc?.balance||0)-Number(i.value||0)); i.closest('tr').querySelector('.remainBal').textContent=fmtMoney(rem);}); recalc(); $('#pUnap').value=state.unappliedBalance.toFixed(2); $('#pApplied').value=state.appliedAmount.toFixed(2);}; document.querySelectorAll('.pickDoc').forEach(c=>c.onchange=auto); document.querySelectorAll('.amtPaid').forEach(i=>i.oninput=updateFromGrid);};
