 if(location.pathname==='/finance/journal/new'){ $('#title').textContent='New Journal Entry'; v.innerHTML=`<form id='newJe' class='card wide'><div class='header-row'><h3>New Journal Entry</h3><div><button type='button' id='saveDoc'>Save</button><button type='button' id='postJe'>Post</button></div></div><label>Post Date<input id='jd' type='date' value='${new Date().toISOString().slice(0,10)}' required></label><label>Post Period<input id='jp' value='${new Date().toISOString().slice(0,7)}' readonly></label><label>Description<input id='jdesc'></label><table id='jlines'><tr><th>Branch</th><th>Branch Code</th><th>Account</th><th>Debit</th><th>Credit</th><th>Reference</th><th>Action</th></tr></table><button type='button' id='addJl'>Add Line</button><div class='je-totals'><div><span>Total Debit</span><b id='newJeDebit'>$0.00</b></div><div><span>Total Credit</span><b id='newJeCredit'>$0.00</b></div><div><span>Difference</span><b id='newJeDifference'>$0.00</b></div></div></form>`; const branches=await api('/api/finance/branches'); const coa=await api('/api/finance/chart-of-accounts'); const acctOpts=coa.map(a=>`<option value='${a.accountNumber}'>${a.accountNumber} - ${a.accountTitle}</option>`).join(''); const addRow=()=>{$('#jlines').insertAdjacentHTML('beforeend',`<tr><td><select class='bname'>${branches.map(b=>`<option value='${b.code}'>${b.name}</option>`)}</select></td><td><input class='bcode' value='100'></td><td><select class='acctSel'>${acctOpts}</select></td><td><input class='dr' type='number' value='0'></td><td><input class='cr' type='number' value='0'></td><td><input class='ref'></td><td><button type='button' class='new-je-remove'>Remove</button></td></tr>`);bindNewLines();}; const refreshTotals=()=>{const rows=[...document.querySelectorAll('#jlines tr')].slice(1),debit=rows.reduce((sum,row)=>sum+Number(row.querySelector('.dr')?.value||0),0),credit=rows.reduce((sum,row)=>sum+Number(row.querySelector('.cr')?.value||0),0),difference=debit-credit;if($('#newJeDebit'))$('#newJeDebit').textContent=fmtMoney(debit);if($('#newJeCredit'))$('#newJeCredit').textContent=fmtMoney(credit);if($('#newJeDifference')){$('#newJeDifference').textContent=fmtMoney(difference);$('#newJeDifference').classList.toggle('err',Math.abs(difference)>.005);}}; const bindNewLines=()=>{document.querySelectorAll('#jlines .dr,#jlines .cr').forEach(input=>input.oninput=refreshTotals);document.querySelectorAll('.new-je-remove').forEach(button=>button.onclick=()=>{button.closest('tr').remove();refreshTotals();});refreshTotals();}; addRow(); addRow(); let saved=null, journalProcessing=false; $('#addJl').onclick=addRow; const calcJePeriod=()=>{$('#jp').value=($('#jd').value||new Date().toISOString().slice(0,10)).slice(0,7);}; $('#jd').onchange=calcJePeriod; calcJePeriod(); const saveJe=async()=>{if(journalProcessing)return null;const lines=[...document.querySelectorAll('#jlines tr')].slice(1).map(r=>({branch:r.querySelector('.bcode').value||r.querySelector('.bname').value,account:r.querySelector('.acctSel').value,debit:Number(r.querySelector('.dr').value||0),credit:Number(r.querySelector('.cr').value||0),sourceReference:r.querySelector('.ref').value}));const debit=lines.reduce((sum,l)=>sum+l.debit,0),credit=lines.reduce((sum,l)=>sum+l.credit,0);if(!$('#jd').value)return alert('A valid transaction date is required.');if(debit<=0||credit<=0)return alert('Journal entry must contain a debit and credit greater than zero.');if(debit!==credit)return alert('Total debits must equal total credits.');journalProcessing=true;const button=$('#saveDoc');button.disabled=true;button.textContent='Saving...';try{saved=await api('/api/finance/journal-transactions',{method:'POST',body:JSON.stringify({transactionDate:$('#jd').value,financialPeriod:$('#jp').value,description:$('#jdesc').value,lines})});showErpDialog({title:'Journal saved',message:`Journal ${saved.jeNumber} was saved successfully.`});navigateTo(`/finance/journal/${saved.jeNumber}`);return saved;}catch(error){showErpDialog({title:'Unable to save journal',message:error.message,details:error.message,type:'error'});return null;}finally{journalProcessing=false;if(button.isConnected){button.disabled=false;button.textContent='Save';}}}; $('#saveDoc').onclick=saveJe; $('#postJe').onclick=async()=>{if(journalProcessing)return;if(!saved)return alert('Save first');journalProcessing=true;const button=$('#postJe');button.disabled=true;button.textContent='Posting...';try{await api('/api/finance/journal-transactions/post',{method:'POST',body:JSON.stringify({jeNumber:saved.jeNumber})});showErpDialog({title:'Journal posted',message:`Journal ${saved.jeNumber} was posted successfully.`});router();}catch(error){showErpDialog({title:'Unable to post journal',message:error.message,details:error.message,type:'error'});}finally{journalProcessing=false;if(button.isConnected){button.disabled=false;button.textContent='Post';}}}; return; }
