restoreAuthentication();

async function renderIncomingDocuments(v){
  $('#title').textContent='Incoming Documents';
  let selectedDocumentId=sessionStorage.getItem('apIncomingSelectedId')||'';
  const [rows,dash,vendors]=await Promise.all([api('/api/ap/incoming-documents'),api('/api/ap/incoming-documents/dashboard'),api('/api/ap/vendors')]);
  
  const kpi=(label,value)=>`<div class='panel'><h4>${label}</h4><div class='big-number'>${value}</div></div>`;
  const grid=ErpDataGrid({id:'incomingDocsGrid',columns:[{key:'id',label:'Document ID',render:r=>`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${r.id}</a>`},{key:'originalFileName',label:'Filename',render:r=>`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${esc(r.originalFileName||r.fileName||'')}</a>`},{key:'uploadedAt',label:'Upload Date',render:r=>esc((r.uploadedAt||r.createdAt||'').slice(0,10))},{key:'source',label:'Source'},{key:'vendorMatch',label:'Vendor',render:r=>{const v=esc(r.vendorMatch?.vendorName||r.extracted?.vendorName||'');return v?`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${v}</a>`:'';}},{key:'invoiceNumber',label:'Vendor Invoice Number',render:r=>r.extracted?.invoiceNumber?`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${esc(r.extracted.invoiceNumber)}</a>`:''},{key:'poNumber',label:'PO Number',render:r=>{const po=r.extracted?.purchaseOrderNumber||r.extracted?.poNumber||'';return po?`<a class='link incoming-select' href='/ap/incoming-documents/${encodeURIComponent(r.id)}/review'>${esc(po)}</a>`:'';}},{key:'invoiceDate',label:'Invoice Date',render:r=>esc(r.extracted?.invoiceDate||'')},{key:'amount',label:'Invoice Total',render:r=>fmtMoney(r.extracted?.grossInvoiceAmount||r.extracted?.totalAmount||0)},{key:'currency',label:'Currency',render:r=>esc(r.extracted?.currency||'USD')},{key:'status',label:'Status'},{key:'actions',label:'Actions',render:r=>`<button class='incoming-select' data-id='${r.id}'>Review</button> <button class='incoming-delete' data-id='${r.id}'>Delete</button>`}],rows});
  const selected=rows.find(r=>r.id===selectedDocumentId)||null;
  const canProcess=!!(selected&&selected.storageKey&&!['PROCESSING','Processing','QUEUED','Queued'].includes(selected.processingStatus||selected.status));
  v.innerHTML=`<div class='header-row'><h3>Incoming Documents</h3><div><button id='uploadPdf'>Upload PDF</button><button id='processInvoice' ${canProcess?'':'disabled'}>Process Invoice</button><button id='processEmail'>Upload AP Email Attachment</button></div></div><div class='grid4'>${kpi('Invoices Processed',dash.invoicesProcessed)}${kpi('Touchless %',dash.touchlessProcessingPct+'%')}${kpi('Exception Rate',dash.exceptionRate+'%')}${kpi('Open Exceptions',dash.openExceptions)}</div><section class='panel'><h4>Upload PDF</h4><p>Select or drag one or more PDFs. Each document is saved, queued, and processed automatically.</p><div id='dropZone' class='upload-zone'><b>Drag & drop invoice PDF here</b><p>${selected?`Selected: ${esc(selected.originalFileName||selected.fileName)} (${esc(selected.status)})`:'No document selected.'}</p><input id='incomingFiles' type='file' accept='.pdf,application/pdf'><input id='incomingEmailFiles' class='hidden' type='file' accept='.pdf,application/pdf'></div><div id='incomingProgress' class='hidden'><p id='progressLabel'>Processing Invoice...</p><progress id='progressBar' max='100' value='0'></progress></div><p id='incomingError' class='form-warning hidden'></p></section><section class='panel'><h4>Incoming Documents List</h4>${grid}</section><section id='incomingReview' class='panel hidden'></section>`;
  bindGrid('incomingDocsGrid');
  const showError=(msg)=>{const e=$('#incomingError'); e.textContent=msg; e.classList.remove('hidden');};
  const fileToDataUrl=(file)=>new Promise((resolve,reject)=>{const reader=new FileReader(); reader.onload=()=>resolve(reader.result); reader.onerror=reject; reader.readAsDataURL(file);});
  const handleUpload=async(files,opts={})=>{ const list=[...(files?.length!==undefined?files:[files])].filter(Boolean); if(!list.length) return; $('#incomingProgress').classList.remove('hidden'); $('#progressLabel').textContent='Uploading PDF...'; $('#progressBar').value=25; for(const file of list){ const dataUrl=await fileToDataUrl(file); const doc=await api('/api/ap/incoming-documents',{method:'POST',body:JSON.stringify({fileName:file.name,mimeType:file.type||'application/pdf',fileData:dataUrl,uploadedBy:'ap.clerk',source:opts.email?'Email Inbox':'PDF Upload',senderEmail:opts.email?'ap@company.com':''})}); } router(); };
  const loadRecognition=async(id)=>api(`/api/ap/incoming-documents/${id}/recognition`);
  const handleProcessInvoice=async()=>{ if(!selectedDocumentId) return showError('Select an uploaded document before processing.'); try{$('#processInvoice').disabled=true; $('#processInvoice').textContent='Processing Invoice...'; $('#incomingProgress').classList.remove('hidden'); $('#progressLabel').textContent='Processing Invoice...'; $('#progressBar').value=10; const rec=await api(`/api/ap/incoming-documents/${selectedDocumentId}/process`,{method:'POST',body:'{}'}); if(rec.status==='Ready for Review'){$('#progressBar').value=100; await loadRecognition(selectedDocumentId); renderReview(rec);} else if(rec.status==='Failed'){throw new Error(rec.processingError||'Recognition failed.');}}catch(e){$('#progressLabel').textContent='Failed'; showError(e.message||'Recognition failed.');} finally {$('#processInvoice').disabled=false; $('#processInvoice').textContent='Process Invoice';} };
  const reconciliation=(rec)=>{const ex=rec.extracted||{}; const lines=ex.lines||[]; const detail=lines.reduce((s,l)=>s+Number(l.lineAmount??l.extendedAmount??(Number(l.qty||0)*Number(l.unitPrice||0))-Number(l.discount||0)),0); const calc=detail+Number(ex.freightAmount||0)+Number(ex.taxAmount||0)-Number(ex.discount||0); const invoice=Number(ex.grossInvoiceAmount||ex.totalAmount||0); const diff=Number((invoice-calc).toFixed(2)); return {detail,calc,invoice,diff,ok:Math.abs(diff)<=0.02};};
  const renderReview=(rec)=>{const ex=rec.extracted||{}; const recon=reconciliation(rec); const vendorOptions=vendors.map(x=>`<option value='${x.id} — ${esc(x.name)}'></option>`).join(''); const vendorValue=rec.vendorMatch?.vendorId?`${rec.vendorMatch.vendorId} — ${rec.vendorMatch.vendorName}`:''; const status=(key)=>ex[key]?'Recognized':'Needs Review'; const field=(label,key,type='text',ro='')=>`<label>${label}<input data-field='${key}' ${ro} type='${type}' value='${esc(ex[key]??'')}'></label><small>${status(key)}</small>`; const pdfSrc=`/api/ap/incoming-documents/${rec.id}/file`; $('#incomingReview').classList.remove('hidden'); $('#incomingReview').innerHTML=`<div class='header-row'><h3>Review ${rec.id}</h3><div><button id='backIncoming'>Back to Incoming Documents</button><button id='prevIncoming'>Previous Document</button><button id='nextIncoming'>Next Document</button><button id='saveDraft'>Save</button><button id='saveNext'>Save and Next</button><button id='approveIncoming'>Approve</button><button id='deleteIncoming'>Delete</button><button id='retryRecognition'>Retry Recognition</button><button id='createBill' ${recon.ok?'':'disabled'}>Save & Create Draft Bill</button>${rec.billId?(rec.bill?.status==='Pending Approval'?"<button id='sendIncomingApproval' disabled>Pending Approval</button>":['Approved','Open','Closed','Voided'].includes(rec.bill?.status)?'':"<button id='sendIncomingApproval'>Send for Approval</button>") : ''}</div></div>${rec.status==='FAILED'?`<div class='panel warn'>${esc(rec.processingError||'Invoice recognition failed. Please review the document and enter the information manually.')}</div>`:''}<section class='panel'><h4>Document Information</h4><div class='erp-header-grid'><label>Document Type<select data-field='documentType'><option ${ex.documentType==='Bill'||ex.documentType==='Vendor Invoice'?'selected':''}>Bill</option><option ${ex.documentType==='Credit Adjustment'?'selected':''}>Credit Adjustment</option><option ${ex.documentType==='Debit Adjustment'?'selected':''}>Debit Adjustment</option></select></label><label>Vendor<input id='incomingVendorLookup' list='incomingVendorList' value='${esc(vendorValue)}' placeholder='Search Vendor Number or Name'><datalist id='incomingVendorList'>${vendorOptions}</datalist></label>${field('Vendor Number','vendorNumber','text','readonly')}${field('Vendor Invoice Number','invoiceNumber')}${field('Invoice Date','invoiceDate','date')}${field('Due Date','dueDate','date')}${field('Payment Terms','paymentTerms')}${field('Currency','currency')}${field('Vendor PO Number','purchaseOrderNumber')}${field('Description','description')}${field('Invoice Total','grossInvoiceAmount','number','readonly')}${field('Tax Amount','taxAmount','number')}${field('Freight Amount','freightAmount','number')}</div></section><section class='panel'><h4>AP Bill Lines</h4><table><tr><th>Branch</th><th>Inventory ID</th><th>Transaction Description</th><th>Quantity</th><th>UOM</th><th>Unit Cost</th><th>Extended Cost</th><th>Discount Amount</th><th>Line Amount</th><th>Account</th><th>Account Description</th><th>Vendor PO Number</th><th>PO Line Number</th><th>Receipt Number</th></tr>${(ex.lines||[]).map((l,i)=>{const qty=Number(l.qty||0),unit=Number(l.unitPrice||0),ext=Number(l.extendedAmount||qty*unit),disc=Number(l.discount||0),amt=Number(l.lineAmount??ext-disc);return `<tr><td><input value='${esc(l.branch||ex.branch||'100')}'></td><td><input value='${esc(l.inventoryId||l.itemCode||'')}'></td><td><input value='${esc(l.description||'')}'></td><td><input type='number' value='${qty}'></td><td><input value='${esc(l.uom||'EA')}'></td><td><input type='number' value='${unit.toFixed(2)}'></td><td><input type='number' value='${ext.toFixed(2)}'></td><td><input type='number' value='${disc.toFixed(2)}'></td><td>${amt.toFixed(2)}</td><td><input value='${esc(l.glAccountSuggestion||'5110')}'></td><td>${esc(l.accountDescription||'Expense')}</td><td><input readonly value='${esc(ex.purchaseOrderNumber||'')}'></td><td><input readonly value='${esc(l.poLineNumber||'')}'></td><td><input readonly value='${esc(l.receiptNumber||'')}'></td></tr>`;}).join('')}</table></section><section class='panel ${recon.ok?'':'warn'}'><h4>Header-to-Line Reconciliation</h4><p>Detail Subtotal ${fmtMoney(recon.detail)} + Freight ${fmtMoney(ex.freightAmount||0)} + Tax ${fmtMoney(ex.taxAmount||0)} = ${fmtMoney(recon.calc)}. Invoice Total: ${fmtMoney(recon.invoice)}. Difference: ${fmtMoney(recon.diff)}.</p>${recon.ok?'':'<p>Invoice total does not match the detail lines. Correct the header or lines before creating the draft bill.</p>'}</section><details class='panel'><summary>Processing Diagnostics</summary><pre>${esc(JSON.stringify(rec.processingDetails||{},null,2))}</pre></details><section class='panel'><h4>Original PDF</h4><button id='togglePdf'>Hide PDF</button><div class='pdf-toolbar sticky'><button type='button'>Zoom +</button><button type='button'>Zoom -</button><button type='button'>Prev Page</button><button type='button'>Next Page</button><button type='button'>Rotate</button><button type='button'>Fit Width</button><input placeholder='Search document text'><a download='${esc(rec.fileName||'invoice.pdf')}' href='${pdfSrc}'><button>Download Original</button></a><a target='_blank' href='${pdfSrc}'><button>Open in New Tab</button></a><button id='retryPreview'>Retry Preview</button></div><iframe class='pdf-frame' src='${pdfSrc}' title='Original PDF'></iframe></section>`; let incomingDirty=false; $('#incomingReview').addEventListener('change',()=>incomingDirty=true); window.onbeforeunload=()=>incomingDirty?'You have unsaved changes. Do you want to save before leaving?':null; lookupFilter('#incomingVendorLookup',null,vendors,(vend)=>{ex.vendorNumber=vend.id; ex.vendorName=vend.name; $('#incomingVendorLookup').value=`${vend.id} — ${vend.name}`;}); const saveReview=async()=>{const out=await api(`/api/ap/incoming-documents/${rec.id}`,{method:'PUT',body:JSON.stringify({status:'In Review',extracted:ex})}); incomingDirty=false; return out;}; $('#backIncoming').onclick=async()=>{await saveReview(); sessionStorage.removeItem('apIncomingSelectedId'); router();}; $('#prevIncoming').onclick=()=>{const i=rows.findIndex(x=>x.id===rec.id),p=rows[i-1]; if(p){sessionStorage.setItem('apIncomingSelectedId',p.id); router();}}; $('#nextIncoming').onclick=()=>{const i=rows.findIndex(x=>x.id===rec.id),n=rows[i+1]; if(n){sessionStorage.setItem('apIncomingSelectedId',n.id); router();}}; $('#saveNext').onclick=async()=>{await saveReview(); const next=rows.find(x=>x.id!==rec.id&&x.status==='Ready for Review'); if(next){sessionStorage.setItem('apIncomingSelectedId',next.id); router();}}; $('#approveIncoming').onclick=async()=>{await api(`/api/ap/incoming-documents/${rec.id}`,{method:'PUT',body:JSON.stringify({status:'Approved',extracted:ex})}); router();}; $('#deleteIncoming').onclick=async()=>{if(confirm('Delete this incoming document? The PDF, recognized data, and review history will be removed.')){await api(`/api/ap/incoming-documents/${rec.id}`,{method:'DELETE'}); sessionStorage.removeItem('apIncomingSelectedId'); router();}}; $('#togglePdf').onclick=()=>{const frame=document.querySelector('.pdf-frame'); const hide=frame.style.display!=='none'; frame.style.display=hide?'none':''; $('#togglePdf').textContent=hide?'Show PDF':'Hide PDF'; sessionStorage.setItem('incomingPdfHidden',hide?'1':'0');}; if(sessionStorage.getItem('incomingPdfHidden')==='1') $('#togglePdf').click(); $('#retryRecognition').onclick=async()=>{try{const next=await api(`/api/ap/incoming-documents/${rec.id}/retry-recognition`,{method:'POST',body:'{}'}); renderReview(next);}catch(e){showError(e.message);}}; $('#retryPreview').onclick=()=>document.querySelector('.pdf-frame').src=`${pdfSrc}?retry=${Date.now()}`; $('#saveDraft').onclick=async()=>{await saveReview(); alert('Review saved.');}; if($('#sendIncomingApproval')&&!$('#sendIncomingApproval').disabled)$('#sendIncomingApproval').onclick=async()=>{const button=$('#sendIncomingApproval');button.disabled=true;button.textContent='Sending...';try{const result=await api(`/api/ap/documents/${encodeURIComponent(rec.billId)}/submit-approval`,{method:'POST',body:'{}'});showErpDialog({title:'Bill sent for approval',message:result.message});button.textContent='Pending Approval';button.disabled=true;}catch(error){showErpDialog({title:'Unable to send bill for approval',message:error.message,details:error.message,type:'error'});if(button.isConnected){button.disabled=false;button.textContent='Send for Approval';}}}; $('#createBill').onclick=async()=>{if(!recon.ok) return showError(`Invoice total does not match the detail lines. Invoice Total: ${fmtMoney(recon.invoice)} Calculated From Lines: ${fmtMoney(recon.calc)} Difference: ${fmtMoney(recon.diff)}`); const res=await api(`/api/ap/incoming-documents/${rec.id}/create-bill`,{method:'POST',body:JSON.stringify({overrideDuplicate:false})}); navigateTo(`/ap/bills/${res.billId}`);};};
  document.querySelectorAll('button.incoming-select').forEach(a=>a.onclick=()=>navigateTo(`/ap/incoming-documents/${encodeURIComponent(a.dataset.id)}/review`)); document.querySelectorAll('.incoming-delete').forEach(b=>b.onclick=async()=>{if(confirm('Delete this incoming document? The PDF, recognized data, and review history will be removed.')){await api('/api/ap/incoming-documents/'+b.dataset.id,{method:'DELETE'}); if(sessionStorage.getItem('apIncomingSelectedId')===b.dataset.id) sessionStorage.removeItem('apIncomingSelectedId'); router();}});
  $('#uploadPdf').onclick=()=>$('#incomingFiles').click();
  $('#processEmail').onclick=()=>$('#incomingEmailFiles').click();
  $('#processInvoice').onclick=handleProcessInvoice;
  $('#incomingFiles').multiple=true; $('#incomingFiles').onchange=e=>handleUpload(e.target.files);
  $('#incomingEmailFiles').multiple=true; $('#incomingEmailFiles').onchange=e=>handleUpload(e.target.files,{email:true});
  $('#dropZone').ondragover=e=>{e.preventDefault();e.currentTarget.classList.add('active');};
  $('#dropZone').ondrop=e=>{e.preventDefault();handleUpload(e.dataTransfer.files);};
  if(selected&&['Queued','Processing','Failed'].includes(selected.status)){ const pdfSrc=`/api/ap/incoming-documents/${selected.id}/file`; $('#incomingReview').classList.remove('hidden'); $('#incomingReview').innerHTML=`<section class='panel ${selected.status==='Failed'?'warn':''}'><h3>${esc(selected.id)} — ${esc(selected.status)}</h3><p>${esc(selected.processingError||'Recognition is in progress. Saved results will appear automatically when processing finishes.')}</p><button id='retryRecognition'>Retry Recognition</button></section><section class='panel'><h4>Original PDF</h4><iframe class='pdf-frame' src='${pdfSrc}' title='Original PDF'></iframe></section>`; $('#retryRecognition').onclick=async()=>{await api(`/api/ap/incoming-documents/${selected.id}/retry-recognition`,{method:'POST',body:'{}'}); router();}; setTimeout(()=>{ if(location.pathname==='/ap/incoming-documents') router(); },2000); } else if(selected&&selected.status==='Ready for Review'&&selected.extracted&&Object.keys(selected.extracted).length) renderReview(selected);
}

async function renderIncomingDocumentReviewPage(v, documentId){
  $('#title').textContent='Incoming Document Review';
  v.innerHTML=`<div class='incoming-review-screen'><div class='review-toolbar'><button id='backIncoming'>Back to Incoming Documents</button><button id='saveReview'>Save</button><button id='retryRecognition'>Retry Processing</button><button id='deleteIncoming'>Delete Document</button><button id='createBill'>Create AP Bill</button><button id='sendReviewApproval' class='hidden'>Send for Approval</button></div><div id='reviewStatus' class='panel'>Loading incoming document...</div><div class='incoming-split' id='incomingSplit'><section class='incoming-pdf-panel' id='pdfPanel'><div class='pdf-toolbar'><button id='togglePdf'>Hide PDF</button><button type='button' id='zoomIn'>Zoom +</button><button type='button' id='zoomOut'>Zoom -</button><button type='button' id='rotatePdf'>Rotate</button><button type='button' id='fitPdf'>Fit to width</button><button type='button' id='fullPdf'>Full screen</button><span id='pdfPageHint'>PDF Loading</span><a id='downloadPdf'><button type='button'>Download original</button></a></div><div id='pdfHolder' class='pdf-holder'><iframe id='incomingPdfFrame' class='pdf-frame' title='Original invoice PDF'></iframe></div></section><div class='split-divider' id='incomingSplitDivider' title='Drag to resize'></div><section class='incoming-form-panel'><div id='processingStatus' class='panel'>Loading saved invoice data...</div><div id='invoiceReviewForm' class='panel'></div><div id='validationPanel' class='panel'></div></section></div></div>`;
  let currentDoc=null, dirty=false, pollTimer=null;
  const pdfUrl=`/api/ap/incoming-documents/${encodeURIComponent(documentId)}/file`;
  const pdfFrame=$('#incomingPdfFrame'); pdfFrame.src=pdfUrl; $('#downloadPdf').href=pdfUrl; $('#downloadPdf').download=`${documentId}.pdf`;
  const pdfPrefKey=`incomingPdfHidden:${documentId}`;
  const applyPdfPref=()=>{const hidden=sessionStorage.getItem(pdfPrefKey)==='1'; $('#pdfHolder').classList.toggle('hidden',hidden); $('#togglePdf').textContent=hidden?'Show PDF':'Hide PDF';};
  $('#togglePdf').onclick=()=>{sessionStorage.setItem(pdfPrefKey,sessionStorage.getItem(pdfPrefKey)==='1'?'0':'1'); applyPdfPref();}; applyPdfPref();
  $('#fullPdf').onclick=()=>$('#pdfPanel').requestFullscreen?.();
  $('#zoomIn').onclick=()=>$('#pdfPanel').style.flexBasis='60%'; $('#zoomOut').onclick=()=>$('#pdfPanel').style.flexBasis='40%'; $('#fitPdf').onclick=()=>$('#pdfPanel').style.flexBasis='50%'; $('#rotatePdf').onclick=()=>{const n=(Number(pdfFrame.dataset.rotation||0)+90)%360; pdfFrame.dataset.rotation=n; pdfFrame.style.transform=`rotate(${n}deg)`;};
  const divider=$('#incomingSplitDivider'); divider.onmousedown=e=>{e.preventDefault(); const split=$('#incomingSplit'); document.onmousemove=ev=>{const pct=Math.max(25,Math.min(75,((ev.clientX-split.getBoundingClientRect().left)/split.offsetWidth)*100)); $('#pdfPanel').style.flexBasis=pct+'%';}; document.onmouseup=()=>{document.onmousemove=null;document.onmouseup=null;};};
  const field=(label,key,type='text',ro='')=>`<label>${label}<input data-field='${key}' ${ro} type='${type}' value='${esc(currentDoc?.extracted?.[key]??'')}'></label>`;
  const renderRight=()=>{const doc=currentDoc||{}, ex=doc.extracted||{}, lines=ex.lines||[]; $('#reviewStatus').innerHTML=`<b>${esc(doc.id||documentId)}</b> — ${esc(doc.status||'Loading')} ${doc.processingError?`<span class='form-warning'>${esc(doc.processingError)}</span>`:''}`; $('#processingStatus').innerHTML=`<h4>${doc.status==='Failed'?'Failed Processing':doc.status==='Processing'||doc.status==='Queued'?'Recognition Processing':'Current Review Status'}</h4><p>${doc.status==='Failed'?esc(doc.processingError||'Recognition failed. The PDF and saved information are still available.'):doc.status==='Processing'||doc.status==='Queued'?'Azure is processing this invoice. You can review the PDF while extraction continues.':esc(doc.status||'')}</p>`; $('#invoiceReviewForm').innerHTML=`<h4>Invoice Verification</h4><div class='erp-header-grid'>${field('Vendor','vendorName')}${field('Vendor invoice number','invoiceNumber')}${field('Invoice date','invoiceDate','date')}${field('Due date','dueDate','date')}${field('Terms','paymentTerms')}${field('Currency','currency')}${field('Purchase order','purchaseOrderNumber')}${field('Description','description')}${field('Subtotal','subtotal','number')}${field('Tax','taxAmount','number')}${field('Freight','freightAmount','number')}${field('Total amount','grossInvoiceAmount','number','readonly')}${field('Department','department')}${field('Cost center','costCenter')}</div><h4>Invoice Lines</h4><table><tr><th>Item</th><th>Description</th><th>Qty</th><th>Unit Price</th><th>Extended</th><th>GL Account</th><th>Department</th><th>Cost Center</th></tr>${lines.map((l,i)=>`<tr><td><input data-line='${i}' data-line-field='itemCode' value='${esc(l.itemCode||l.inventoryId||'')}'></td><td><input data-line='${i}' data-line-field='description' value='${esc(l.description||'')}'></td><td><input data-line='${i}' data-line-field='qty' type='number' value='${esc(l.qty||l.quantity||0)}'></td><td><input data-line='${i}' data-line-field='unitPrice' type='number' value='${esc(l.unitPrice||0)}'></td><td><input data-line='${i}' data-line-field='extendedAmount' type='number' value='${esc(l.extendedAmount||0)}'></td><td><input data-line='${i}' data-line-field='glAccountSuggestion' value='${esc(l.glAccountSuggestion||'')}'></td><td><input data-line='${i}' data-line-field='department' value='${esc(l.department||'')}'></td><td><input data-line='${i}' data-line-field='costCenter' value='${esc(l.costCenter||'')}'></td></tr>`).join('')||`<tr><td colspan='8'>No line items saved yet.</td></tr>`}</table>`; $('#validationPanel').innerHTML=`<h4>Validation and Exceptions</h4><p>${esc((doc.validationWarnings||doc.exceptions||[]).map(x=>x.message||x).join('\n')||'No validation warnings saved.')}</p><details><summary>Confidence scores and processing history</summary><pre>${esc(JSON.stringify({confidence:doc.confidence||{},processingDetails:doc.processingDetails||{},auditTrail:doc.auditTrail||[]},null,2))}</pre></details>`; $('#invoiceReviewForm').querySelectorAll('input').forEach(inp=>inp.oninput=()=>{dirty=true; currentDoc.extracted=currentDoc.extracted||{}; if(inp.dataset.field) currentDoc.extracted[inp.dataset.field]=inp.value; if(inp.dataset.line){const line=currentDoc.extracted.lines[Number(inp.dataset.line)]; line[inp.dataset.lineField]=inp.value;}}); };
  const loadDoc=async()=>{currentDoc=await api(`/api/ap/incoming-documents/${encodeURIComponent(documentId)}`);renderRight();const send=$('#sendReviewApproval');if(send){const status=currentDoc.bill?.status||'';send.classList.toggle('hidden',!currentDoc.billId||['Approved','Open','Closed','Voided'].includes(status));send.disabled=status==='Pending Approval';send.textContent=status==='Pending Approval'?'Pending Approval':'Send for Approval';}};
  const save=async()=>{if(!currentDoc)return; currentDoc=await api(`/api/ap/incoming-documents/${encodeURIComponent(documentId)}`,{method:'PUT',body:JSON.stringify({status:currentDoc.status==='Ready for Review'?'In Review':currentDoc.status,extracted:currentDoc.extracted||{}})}); dirty=false; renderRight();};
  $('#saveReview').onclick=save; $('#backIncoming').onclick=async()=>{if(dirty&&confirm('Save changes before returning to Incoming Documents?')) await save(); navigateTo('/ap/incoming-documents');};
  $('#retryRecognition').onclick=async()=>{currentDoc=await api(`/api/ap/incoming-documents/${encodeURIComponent(documentId)}/retry-recognition`,{method:'POST',body:'{}'}); renderRight(); startPolling();};
  $('#deleteIncoming').onclick=async()=>{if(confirm('Delete this incoming document? The PDF, recognized data, and review history will be removed.')){await api(`/api/ap/incoming-documents/${encodeURIComponent(documentId)}`,{method:'DELETE'}); navigateTo('/ap/incoming-documents');}};
  $('#sendReviewApproval').onclick=async()=>{if(!currentDoc?.billId)return;const button=$('#sendReviewApproval');let submitted=false;button.disabled=true;button.textContent='Sending...';try{const result=await api(`/api/ap/documents/${encodeURIComponent(currentDoc.billId)}/submit-approval`,{method:'POST',body:'{}'});submitted=true;showErpDialog({title:'Bill sent for approval',message:result.message});button.textContent='Pending Approval';}catch(error){showErpDialog({title:'Unable to send bill for approval',message:error.message,details:error.message,type:'error'});}finally{if(button.isConnected&&!submitted){button.disabled=false;button.textContent='Send for Approval';}}}; $('#createBill').onclick=async()=>{if(dirty) await save(); const res=await api(`/api/ap/incoming-documents/${encodeURIComponent(documentId)}/create-bill`,{method:'POST',body:JSON.stringify({overrideDuplicate:false})}); navigateTo(`/ap/bills/${res.billId}`);};
  const finalStatuses=new Set(['Ready for Review','In Review','Needs Attention','Failed','Approved','Posted','Converted','Duplicate','Rejected']);
  const poll=async()=>{try{const next=await api(`/api/ap/incoming-documents/${encodeURIComponent(documentId)}`); currentDoc={...currentDoc,...next}; renderRight(); if(finalStatuses.has(currentDoc.status)&&pollTimer){clearInterval(pollTimer); pollTimer=null;}}catch(e){$('#processingStatus').innerHTML=`<h4>Failed Processing</h4><p>${esc(e.message)}</p>`; if(pollTimer) clearInterval(pollTimer);}};
  const startPolling=()=>{if(pollTimer) clearInterval(pollTimer); if(!finalStatuses.has(currentDoc?.status)) pollTimer=setInterval(poll,2000);};
  await loadDoc(); startPolling(); window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='You have unsaved changes. Do you want to save before leaving?';}});
}
